import Head from 'next/head';
import fetch from 'isomorphic-unfetch';
const WooCommerceAPI = require('woocommerce-api');
function Index({ data }) {

    return (
        <div className="container">
            <Head>
                <title>Create Next App</title>
                <link rel="icon" href="/favicon.ico" />
            </Head>


            <main>
                {console.log("ss", data)}
            </main>

        </div>

    );
}

const WooCommerceConfig = new WooCommerceAPI({
    url: 'http://localhost:8888/',
    consumerKey: 'ck_14bc1d5dfe2ef575063dc21b96de63563284a187',
    consumerSecret: 'cs_75d6c167e18a7eaac8ed7bc3e5bf32ee660c0227',
    wpAPI: true,
    version: 'wc/v1'
});


Index.getInitialProps = async () => {
    const res = await fetch('http://localhost:8888/wp-json/wc/v3/products');
    let data = await res.json();
    return { data }
}

export default Index;
